import assert from 'node:assert/strict';import fs from 'node:fs';import {AnyDocParser} from '../../../src/lib/parser/anydocParser.js';import {evaluateDuplicateEvidence,type DuplicateEvidenceObservation} from '../../cpaOrganization/duplicateEvidenceIntegrityEngine.js';import {DUP_ENGAGEMENT_ID,DUP_WORKSPACE_ID,dupPath,loadDup,sha256} from './duplicateEvidenceFixture.js';const parser=new AnyDocParser();
const pdfFields=(text:string)=>{const grab=(label:string)=>{const line=text.split(/\r?\n/).map(x=>x.trim()).find(x=>x.startsWith(label+' '));if(!line)throw new Error(`PDF_FIELD_MISSING:${label}`);return line.slice(label.length).trim();};return {identity:{documentType:'RECEIPT',issuer:grab('ISSUER'),documentNumber:grab('RECEIPT'),documentDate:grab('DATE'),currency:grab('CURRENCY')},material:{subtotal:Number(grab('SUBTOTAL USD')),salesTax:Number(grab('SALES TAX USD')),total:Number(grab('TOTAL USD')),paymentAmount:Number(grab('PAYMENT USD'))}};};
const pdfObs=async(id:string,filename:string):Promise<DuplicateEvidenceObservation>=>{const bytes=loadDup(filename),sha=sha256(bytes);const doc:any=await parser.parse({filename,originalName:filename,mimeType:'application/pdf',size:bytes.length,buffer:bytes},{detectedType:'pdf'} as any);const text=String(doc.raw_text||'');const f=pdfFields(text);const artifact=`artifact-pdf-${sha.slice(0,24)}`;return {sourceKind:'PDF',documentId:id,workspaceId:DUP_WORKSPACE_ID,sourceSha256:sha,sourceArtifactId:artifact,provenanceId:`prov-${id}`,sourceText:text,identityFields:f.identity,materialFields:f.material,sourceCoordinate:{coordinateId:`coord-${id}`,sourceArtifactId:artifact,sourceSha256:sha,sourceType:'PDF',pageNumber:1,rawLiteral:`TOTAL USD ${Number(f.material.total).toFixed(2)}`,nativeTextAvailable:true,evidenceMode:'NATIVE_TEXT',extractionMethod:'pdf-parse-native-text',extractionVersion:'1'}};};
const imageObs=(key:string,id:string):DuplicateEvidenceObservation=>{const man=JSON.parse(fs.readFileSync(dupPath('duplicate-image-manifest.json'),'utf8')).files[key];const artifact=`artifact-image-${man.sha256.slice(0,24)}`;return {sourceKind:'IMAGE',documentId:id,workspaceId:DUP_WORKSPACE_ID,sourceSha256:man.sha256,sourceArtifactId:artifact,provenanceId:`prov-${id}`,sourceText:man.region.rawLiteral,identityFields:man.identity,materialFields:man.material,sourceCoordinate:{coordinateId:`coord-${id}`,sourceArtifactId:artifact,sourceSha256:man.sha256,sourceType:'IMAGE',pageNumber:1,imageWidth:man.region.imageWidth,imageHeight:man.region.imageHeight,boundingBox:man.region.boundingBox,ocrRegionId:`dup-total-${key}`,rawLiteral:man.region.rawLiteral,normalizedLiteral:man.region.rawLiteral,extractionMethod:'academy-accepted-receipt-region',extractionVersion:'1'}};};
const fact=(o:any)=>({id:`fact-${o.documentId}`,workspaceId:o.workspaceId,documentId:o.documentId,canonicalMetric:'duplicate_evidence_observation',labelOriginal:`${o.sourceKind} duplicate evidence observation`,labelNormalized:`${o.sourceKind} duplicate evidence observation`,valueOriginal:String(o.materialFields.total),valueFunctional:Number(o.materialFields.total),normalizedValue:Number(o.materialFields.total),currencyOriginal:'USD',functionalCurrency:'USD',reportingPeriod:'FY 2026',status:'REVIEW_REQUIRED',verificationStatus:'REVIEW_REQUIRED',evidenceStatus:'CONFIRMED',sourceDocument:o.documentId,documentTitle:o.documentId,sourceText:o.sourceText,sourceSha256:o.sourceSha256,sourceArtifactId:o.sourceArtifactId,sourceProvenanceId:o.provenanceId,sourceProvenanceIds:[o.provenanceId],sourceCoordinate:o.sourceCoordinate,sourceCoordinates:[o.sourceCoordinate],provenanceCoordinates:[o.sourceCoordinate],sourceExtractionMethod:o.sourceCoordinate.extractionMethod,sourceExtractionVersion:o.sourceCoordinate.extractionVersion});
export async function prepareDuplicateEvidence(){const imageManifest=JSON.parse(fs.readFileSync(dupPath('duplicate-image-manifest.json'),'utf8')).files;assert.equal(imageManifest['image-base'].sha256,imageManifest['image-exact'].sha256);assert.notEqual(imageManifest['image-base'].sha256,imageManifest['image-cosmetic'].sha256);assert.equal(imageManifest['image-base'].identityVisualHash,imageManifest['image-cosmetic'].identityVisualHash);assert.equal(imageManifest['image-base'].materialVisualHash,imageManifest['image-cosmetic'].materialVisualHash);assert.notEqual(imageManifest['image-base'].materialVisualHash,imageManifest['image-material'].materialVisualHash);
 const observations:DuplicateEvidenceObservation[]=[await pdfObs('doc-pdf-base','dup-pdf-base.pdf'),await pdfObs('doc-pdf-exact','dup-pdf-exact-copy.pdf'),await pdfObs('doc-pdf-cosmetic','dup-pdf-cosmetic.pdf'),await pdfObs('doc-pdf-material','dup-pdf-material-conflict.pdf'),imageObs('image-base','doc-image-base'),imageObs('image-exact','doc-image-exact'),imageObs('image-cosmetic','doc-image-cosmetic'),imageObs('image-material','doc-image-material')];
 const cleanObs=observations.filter(o=>!o.documentId.endsWith('-material'));const cleanReview=evaluateDuplicateEvidence({observations:cleanObs,expectedWorkspaceId:DUP_WORKSPACE_ID,reviewId:'duplicate-clean'});const conflictReview=evaluateDuplicateEvidence({observations,expectedWorkspaceId:DUP_WORKSPACE_ID,reviewId:'duplicate-conflict'});const tampered=JSON.parse(JSON.stringify(cleanObs));tampered[0].sourceCoordinate.sourceSha256='0'.repeat(64);const invalidReview=evaluateDuplicateEvidence({observations:tampered,expectedWorkspaceId:DUP_WORKSPACE_ID,reviewId:'duplicate-invalid'});const facts=observations.map(fact);const documents=observations.map(o=>({id:o.documentId,filename:o.documentId+(o.sourceKind==='PDF'?'.pdf':'.png'),sha256:o.sourceSha256,workspaceId:DUP_WORKSPACE_ID,pageCount:1}));return {observations,cleanReview,conflictReview,invalidReview,facts,documents};}
export async function buildDuplicateEvidenceEngagement(){const p=await prepareDuplicateEvidence();return {engagementId:DUP_ENGAGEMENT_ID,workspaceId:DUP_WORKSPACE_ID,classification:'ACADEMY',isCustomer:false,clientName:'Eve Academy Duplicate Evidence',entityName:'Eve Academy Duplicate Evidence',title:'Duplicate Evidence Integrity',period:'FY 2026',framework:'US_GAAP',functionalCurrency:'USD',currentStage:'EVIDENCE_REVIEW',openReviewNotesCount:1,facts:p.facts,canonicalFacts:p.facts,documents:p.documents,reports:[],findings:[{id:'finding-duplicate-material-conflict',topic:'Material near-duplicate conflict',description:'Same-identity source contains materially changed accounting content and remains blocked pending reconciliation.',status:'OPEN',sourceReferences:p.conflictReview.evidenceRefs}],periods:['FY 2026'],continuation:null,duplicateEvidenceReview:p.conflictReview};}
